// Unicode emoji dataset mirroring Discord's emoji picker: categories, shortcodes, skin tones, lookup/search and
// ":shortcode:" replacement. Pure C23, static const tables (generated by scripts/gen_emoji_data.py), no heap use:
// every function writes only into caller-provided buffers and is safe to call from any thread.
#pragma once
#include <stddef.h>
#include <stdint.h>

typedef enum ccord_emoji_category : uint8_t {
  CCORD_EMOJI_PEOPLE,
  CCORD_EMOJI_NATURE,
  CCORD_EMOJI_FOOD,
  CCORD_EMOJI_ACTIVITIES,
  CCORD_EMOJI_TRAVEL,
  CCORD_EMOJI_OBJECTS,
  CCORD_EMOJI_SYMBOLS,
  CCORD_EMOJI_FLAGS,
  CCORD_EMOJI_CATEGORY_COUNT
} ccord_emoji_category;

typedef struct ccord_emoji_entry {
  const char *utf8;               // fully-qualified default-tone sequence
  const char *name;               // primary shortcode WITHOUT colons, e.g. "thumbsup"
  const char *const *aliases;     // NULL-terminated array of further shortcodes, or nullptr
  const char *cldr_name;          // Unicode CLDR short name, e.g. "thumbs up"
  ccord_emoji_category category;
  bool has_skin_tones;            // the five uniform tone variants exist (see ccord_emoji_with_tone)
} ccord_emoji_entry;

// Number of base emoji (skin-tone variants are not separate entries).
size_t ccord_emoji_count(void);
// Entry i in Discord/Unicode order, grouped by category; nullptr when out of range.
const ccord_emoji_entry *ccord_emoji_at(size_t i);
// "People", "Nature", "Food", "Activities", "Travel", "Objects", "Symbols", "Flags" ("" when out of range).
const char *ccord_emoji_category_name(ccord_emoji_category c);
// Contiguous index range of a category (0, 0 when out of range). Either out pointer may be null.
void ccord_emoji_category_range(ccord_emoji_category c, size_t *first, size_t *count);

// tone 0 = default, 1..5 = light..dark (U+1F3FB..U+1F3FF). Writes a NUL-terminated sequence and returns its
// length; entries without tone variants (or an invalid tone) yield the default sequence. Returns 0 (and writes an
// empty string when cap > 0) if it does not fit.
size_t ccord_emoji_with_tone(const ccord_emoji_entry *e, int tone, char *out, size_t cap);

// Exact, case-insensitive lookup of a primary shortcode or alias, without colons. O(log n).
const ccord_emoji_entry *ccord_emoji_find_shortcode(const char *name, size_t len);
// Exact lookup of a default or toned sequence, including unqualified/minimally-qualified spellings (e.g. missing
// U+FE0F). *out_tone (may be null) receives 0 for the default tone or 1..5. O(log n).
const ccord_emoji_entry *ccord_emoji_find_utf8(const char *s, size_t len, int *out_tone);

// Ranked search (case-insensitive; ' ' and '_' are equivalent; surrounding colons ignored). Order: exact name/alias,
// prefix of name, prefix of alias, substring of name/alias, substring of CLDR name; stable by dataset order inside a
// tier. Writes up to cap entry indices (for ccord_emoji_at) and returns how many.
size_t ccord_emoji_search(const char *query, size_t qlen, size_t *out_idx, size_t cap);
// Prefix completion for ":sho" autocomplete: names/aliases starting with the prefix, ranked exact, name prefix,
// alias prefix, then dataset order. Uses the sorted index (O(log n + matches)).
size_t ccord_emoji_complete(const char *prefix, size_t plen, size_t *out_idx, size_t cap);

// Replaces every complete ":shortcode:" (and ":shortcode::skin-tone-N:", N 2..6, for emoji with tone variants)
// known to the dataset with its Unicode emoji. Unknown :tokens:, text inside `code` / ```code blocks``` and
// <:name:id> / <a:name:id> custom emoji tokens are left untouched. Always NUL-terminates when cap > 0 and returns
// the output length (excluding NUL); when cap is too small the output is truncated at a character boundary and
// never splits a UTF-8 sequence.
size_t ccord_emoji_replace_shortcodes(const char *in, size_t len, char *out, size_t cap);
